	//
	// Deliberately gated HERE rather than inside the coordinator. The health
	// check is blind to absolute_git_hook_path by design —
	// validNativeHookCommandPrefix accepts the bare `entire` form and an
	// absolute path equally — so an early-out inside the coordinator would stop
	// honoring a flipped flag, which is the regression b785b265e fixed. This
	// caller passes the ambient setting and never changes it; the callers that
	// do act on an explicit flag (`entire enable`, `configure`, `doctor`) call
	// the coordinator directly and still run it in full.
	if health := CheckGitHookIntegration(ctx); health.State == GitHookIntegrationCurrent {
